"""The build's half of rtc.js's checks on what a peg writes as a literal.

rtc.js checks every value a page hands WebRTC when the page runs, so a
mistake here fails closed. The build checks what it can see first, so the
person learns at build what the browser would refuse:

- **C9**, an ICE server URL: ``ICE_URL`` and ``ICE_URL_MAX`` are rtc.js's own
  text, copied, and ``tests/ui/test_rtc_refusals.py`` holds the copy equal to
  rtc.js's and to its verdict on every URL one edit from a valid one.
- **C11**, a camera's URL: the build cannot know the page's origin, so a
  literal passes only if rtc.js would take it on some page. ``SCHEME``,
  ``CONTROL`` and ``STREAM_URL_MAX`` are rtc.js's. Where a URL names a host,
  the build also holds it to what every engine's URL parser reads the same
  way, since rtc.js refuses a URL the parser cannot read.
- **C15**, the build half: the names rtc.js's belt would call as a
  page's handler.

Nothing here reads a value the page works out: that stays rtc.js's.
"""
from __future__ import annotations

import encodings.idna
import ipaddress
import re
import unicodedata

# ---- C9 ------------------------------------------------------------------

#: rtc.js's ``var ICE_URL = /.../;``, the text between the slashes. Matched
#: with ``re.fullmatch``: Python's ``$`` also matches before a final line
#: break, which JavaScript's does not, so a URL ending in one must not pass.
#: The compiler holds no ICE URL with a host, not even as an example: the
#: SDK names no server, and the peg's author chooses them.
ICE_URL = (r"^(stun|turns?):(\[[0-9A-Fa-f:.]{2,45}\]|[A-Za-z0-9](?:[A-Za-z0-9-]"
           r"{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}"
           r"[A-Za-z0-9])?)*)(?::([0-9]{1,5}))?(\?transport=(?:udp|tcp))?$")
#: rtc.js's ``ICE_URL_MAX``, in UTF-8 bytes.
ICE_URL_MAX = 512
_ICE_URL = re.compile(ICE_URL)

ICE_URL_RULE = (
    "An ICE server URL is stun:, turn: or turns:, then a host name or a "
    "bracketed IPv6 address, an optional :port from 1 to 65535 and, for "
    "turn: and turns: only, ?transport=udp or ?transport=tcp; nothing else "
    "(no //, no user name, no path), at most 512 bytes")


def ice_url_ok(url: str) -> bool:
    """Whether rtc.js's C9 takes ``url``: its pattern, its byte bound, a
    port of 1 to 65,535, and a transport for turn and turns only."""
    if not isinstance(url, str) or len(url.encode("utf-8")) > ICE_URL_MAX:
        return False
    m = _ICE_URL.fullmatch(url)
    if m is None:
        return False
    if m.group(4) and m.group(1) == "stun":
        return False
    return m.group(3) is None or 1 <= int(m.group(3)) <= 65535


def ice_urls(value):
    """Each literal ``urls`` string in the parsed value of ``ice_servers=``:
    a list of server dicts, each one's ``urls`` a string or a list of them,
    through either arm of a condition at any of those places. Module
    constants are already inlined there. Anything else is left to rtc.js."""
    for servers in _arms(value, "list"):
        for server in servers["items"]:
            for entry in _arms(server, "dict"):
                for key, urls in entry["pairs"]:
                    if key == "urls":
                        yield from _urls(urls)


def _arms(value, expr):
    """``value``, or each arm of a condition it is, that is an ``expr``
    node: a list or a dict literal."""
    if isinstance(value, dict) and value.get("expr") == expr:
        yield value
    elif isinstance(value, dict) and value.get("expr") == "cond":
        for arm in (value.get("then"), value.get("else")):
            yield from _arms(arm, expr)


def _urls(value, in_list=False):
    """The strings ``urls`` holds: itself, or each item of its list."""
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict) and value.get("expr") == "cond":
        for arm in (value.get("then"), value.get("else")):
            yield from _urls(arm, in_list)
    elif (isinstance(value, dict) and value.get("expr") == "list"
            and not in_list):
        for item in value["items"]:
            yield from _urls(item, True)


# ---- C11 -----------------------------------------------------------------

#: rtc.js's ``SCHEME``, ``CONTROL`` and ``STREAM_URL_MAX``.
SCHEME = r"^[A-Za-z][A-Za-z0-9+.-]*:"
CONTROL = r"[\u0000-\u001f\u007f]"
STREAM_URL_MAX = 2048
#: The schemes rtc.js's ``STREAM_SCHEMES`` takes.
STREAM_SCHEMES = ("https:", "blob:")
_SCHEME = re.compile(SCHEME)
_CONTROL = re.compile(CONTROL)

#: A camera's stream no <video> plays, by scheme, and what it is called.
UNPLAYABLE = {
    "rtsp:": "RTSP", "rtsps:": "RTSP", "rtmp:": "RTMP", "rtmps:": "RTMP",
    "srt:": "SRT", "ws:": "WebSocket", "wss:": "WebSocket",
}

STREAM_URL_RULE = (
    "A camera's URL is https:, blob: (the person's own file) or a path on "
    "the page's own origin (/cam/1.webm, cam.webm), of 1 to 2,048 bytes, "
    "with no control character and no space first")

# A host every engine reads as itself: labels of letters, digits, '-' and
# '_', one trailing dot at most. A last label that is a number makes a URL
# parser read the whole host as IPv4, so then it must be a dotted quad.
_LABEL = r"[A-Za-z0-9_-]+"
_DOMAIN = re.compile(rf"{_LABEL}(?:\.{_LABEL})*\.?")
_OCTET = r"(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])"
_DOTTED_QUAD = re.compile(rf"{_OCTET}(?:\.{_OCTET}){{3}}\.?")
_NUMBER = re.compile(r"[0-9]+|0[xX][0-9A-Fa-f]*")
_PORT = re.compile(r"[0-9]*")


def _idn_label_ok(label: str) -> bool:
    """An ``xn--`` label every engine reads back to itself: one that
    decodes, to lower-case letters and digits in NFC, and that IDNA
    encodes again to the same label. Stricter than a URL parser, never
    looser (measured against node's for each case the tests hold)."""
    try:
        decoded = label[4:].encode("ascii").decode("punycode")
        again = encodings.idna.ToASCII(decoded).decode("ascii")
    except (UnicodeError, ValueError):
        return False
    return (bool(decoded) and not decoded.isascii()
            and unicodedata.normalize("NFC", decoded) == decoded
            and decoded == decoded.lower()
            and all(c.isalnum() or c == "-" for c in decoded)
            and again == label)


def _host_ok(host: str) -> bool:
    if host.startswith("["):
        inner = host[1:-1] if host.endswith("]") else ""
        if not re.fullmatch(r"[0-9A-Fa-f:.]+", inner):
            return False
        try:
            ipaddress.IPv6Address(inner)
        except ValueError:
            return False
        return True
    if not _DOMAIN.fullmatch(host):
        return False
    labels = (host[:-1] if host.endswith(".") else host).split(".")
    if _NUMBER.fullmatch(labels[-1]):
        return _DOTTED_QUAD.fullmatch(host) is not None
    return all(_idn_label_ok(lab.lower()) for lab in labels
               if lab[:4].lower() == "xn--")


def _authority_ok(authority: str) -> bool:
    """``host[:port]``. A user name or a password is refused with the rest,
    since ``@`` is no character of a host."""
    if authority.startswith("["):
        close = authority.find("]")
        host, rest = authority[:close + 1], authority[close + 1:]
        if close < 0 or (rest and not rest.startswith(":")):
            return False
        port = rest[1:]
    else:
        host, _, port = authority.partition(":")
    return (bool(host) and _host_ok(host) and _PORT.fullmatch(port) is not None
            and (port == "" or int(port) <= 65535))


def stream_url_problem(url: str) -> "tuple[str, str] | None":
    """None when rtc.js's C11 would take ``url`` on some page, else
    ``(reason, what to say)``. The reasons: ``size``, ``control``,
    ``space``, ``unplayable``, ``scheme``, ``another-host`` and ``host``."""
    if not 1 <= len(url.encode("utf-8")) <= STREAM_URL_MAX:
        return "size", f"{STREAM_URL_RULE}, and this one is " + (
            "empty" if not url else f"{len(url.encode('utf-8')):,} bytes")
    if _CONTROL.search(url):
        return "control", (f"{STREAM_URL_RULE}, and this one holds a control "
                           "character, which a URL parser drops or reads past")
    if url.startswith(" "):
        return "space", (f"{STREAM_URL_RULE}. A URL parser strips a space "
                         "first, so what follows it would be read as another "
                         "URL than the one written: take the space out")
    m = _SCHEME.match(url)
    if m is None:
        if url.startswith(("//", "\\", "/\\")):
            return "another-host", (
                f"{STREAM_URL_RULE}. One starting //, \\ or /\\ names another "
                "host, which a page takes only from its own origin: write "
                "https://<host>/... for a camera on another host")
        return None
    scheme = m.group(0).lower()
    if scheme in UNPLAYABLE:
        name = UNPLAYABLE[scheme]
        return "unplayable", (
            f"{scheme} is a camera's {name} stream, which no browser can play "
            "in a <video>. Put a gateway in front of the camera that serves "
            "it over https (as WebRTC, HLS or MP4), such as MediaMTX or "
            "go2rtc, and give HTMLVideoElement that https: URL")
    if scheme not in STREAM_SCHEMES:
        return "scheme", (f"{STREAM_URL_RULE}, and {scheme} is none of them"
                          + (": use https:" if scheme == "http:" else ""))
    rest = url[m.end():]
    if scheme == "https:" and rest[:2] and all(c in "/\\" for c in rest[:2]):
        authority = re.split(r"[/\\?#]", rest.lstrip("/\\"), maxsplit=1)[0]
    elif scheme == "blob:" and rest.startswith("//"):
        authority = re.split(r"[/?#]", rest[2:], maxsplit=1)[0]
    else:
        return None
    if not _authority_ok(authority):
        return "host", (
            f"{STREAM_URL_RULE}, and {authority!r} is no host the build can "
            "be sure every browser reads as written: write a host name of "
            "letters, digits, '-', '_' and '.' (an international one in its "
            "xn-- form), an IPv4 address such as 192.0.2.1 or a bracketed "
            "IPv6 one such as [2001:db8::1], an optional :port up to 65535, "
            "and no user name or password")
    return None


# ---- C15 -----------------------------------------------------------------

#: What rtc.js's belt calls as a page's handler: a word of this pattern,
#: not starting with _ (the runtime's own), and none of these names.
HANDLER_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
HANDLER_DENY = frozenset(("constructor", "render", "build"))


def handler_name_ok(name) -> bool:
    return (isinstance(name, str) and HANDLER_NAME.fullmatch(name) is not None
            and not name.startswith("_") and name not in HANDLER_DENY)
